scalar_spiral.normalized_source:
def _spiral(self, d: Float64) -> DirectedPoint:
    var k0 = self.curvature_start
    var rate = (self.curvature_end - self.curvature_start) / self.length
    var reach = max(abs(k0), abs(k0 + rate * d))
    var pieces = 1 + Int(ceil(d * (1.0 + reach)))
    var step = d / Float64(pieces)
    var nodes = materialize[_GL_NODES]()
    var weights = materialize[_GL_WEIGHTS]()
    var x = Float64(0.0)
    var y = Float64(0.0)
    for piece in range(pieces):
        var start = step * Float64(piece)
        for i in range(5):
            var t = start + step * 0.5 * (1.0 + nodes[i])
            var theta = self.heading + t * (k0 + 0.5 * rate * t)
            x += step * 0.5 * weights[i] * cos(theta)
            y += step * 0.5 * weights[i] * sin(theta)
    return DirectedPoint(
        self.x + x,
        self.y + y,
        0.0,
        self.heading + d * (k0 + 0.5 * rate * d),
    )

scalar_sincos.normalized_source:
def _curve_sincos(value: Float64) -> Tuple[Float64, Float64]:
    if not isfinite(value):
        return (sin(value), cos(value))
    if abs(value) > _PHASE_LIMIT:
        return (
            min(max(sin(value), -1.0), 1.0),
            min(max(cos(value), -1.0), 1.0),
        )
    var quadrant = Int(floor(value * _INV_HALF_PI + 0.5))
    var high = Float64(quadrant) * _HALF_PI_HIGH
    var low = Float64(quadrant) * _HALF_PI_LOW
    var reduced = (value - high) - low
    var square = reduced * reduced
    var sine = reduced * _scalar_polynomial(
        materialize[_SIN_COEFFICIENTS](), square
    )
    var cosine = _scalar_polynomial(materialize[_COS_COEFFICIENTS](), square)
    var mode = quadrant & 3
    if mode == 0:
        return (sine, cosine)
    if mode == 1:
        return (cosine, -sine)
    if mode == 2:
        return (-sine, -cosine)
    return (-cosine, sine)

scalar_trig_wrappers.normalized_source:
def _curve_sin(value: Float64) -> Float64:
    return _curve_sincos(value)[0]
def _curve_cos(value: Float64) -> Float64:
    return _curve_sincos(value)[1]

ideal_sincos_selector.normalized_source:
def _sincos_expression[derivatives: Bool](
    value: _JetExpression[derivatives]
) -> Tuple[_JetExpression[derivatives], _JetExpression[derivatives]]:
    comptime Expression = _JetExpression[derivatives]
    var domain = value.rounded_value()
    if not domain.is_finite():
        return (
            _uncertain_expression[derivatives](_Interval.whole()),
            _uncertain_expression[derivatives](_Interval.whole()),
        )
    if domain.magnitude() > _PHASE_LIMIT:
        if domain.low > _PHASE_LIMIT or domain.high < -_PHASE_LIMIT:
            var unknown = _uncertain_expression[derivatives](
                _Interval(-1.0, 1.0)
            )
            return (unknown, unknown)
        return (
            _uncertain_expression[derivatives](_Interval.whole()),
            _uncertain_expression[derivatives](_Interval.whole()),
        )
    var selection = (
        value * Expression.constant(_INV_HALF_PI) + Expression.constant(0.5)
    ).rounded_value()
    var low = Int(floor(selection.low))
    var high = Int(floor(selection.high))
    if low == high:
        return _sincos_branch_expression(value, low)
    if high - low > 4:
        return (
            _uncertain_expression[derivatives](_Interval.whole()),
            _uncertain_expression[derivatives](_Interval.whole()),
        )
    var source = Expression.variable(domain.low, domain.high)
    var result = _sincos_branch_expression(source, low)
    var sine = result[0].rounded_value()
    var cosine = result[1].rounded_value()
    var quadrant = low + 1
    while quadrant <= high:
        var piece = _sincos_branch_expression(source, quadrant)
        sine = sine.hull(piece[0].rounded_value())
        cosine = cosine.hull(piece[1].rounded_value())
        quadrant += 1
    return (
        _uncertain_expression[derivatives](sine),
        _uncertain_expression[derivatives](cosine),
    )

ideal_horner.normalized_source:
def _expression_polynomial[n: Int, derivatives: Bool](
    coefficients: Array[Float64, n], x: _JetExpression[derivatives]
) -> _JetExpression[derivatives]:
    comptime Expression = _JetExpression[derivatives]
    var result = Expression.constant(coefficients[n - 1])
    var i = n - 2
    while i >= 0:
        result = result * x + Expression.constant(coefficients[i])
        i -= 1
    return result

ideal_sincos_branch.normalized_source:
def _sincos_branch_expression[derivatives: Bool](
    value: _JetExpression[derivatives], quadrant: Int
) -> Tuple[_JetExpression[derivatives], _JetExpression[derivatives]]:
    comptime Expression = _JetExpression[derivatives]
    var high = Float64(quadrant) * _HALF_PI_HIGH
    var low = Expression.constant(Float64(quadrant)) * Expression.constant(
        _HALF_PI_LOW
    )
    var reduced = (value - Expression.constant(high)) - low
    var square = reduced * reduced
    var sine = reduced * _expression_polynomial(
        materialize[_SIN_COEFFICIENTS](), square
    )
    var cosine = _expression_polynomial(materialize[_COS_COEFFICIENTS](), square)
    var mode = quadrant & 3
    if mode == 0:
        return (sine, cosine)
    if mode == 1:
        return (cosine, -sine)
    if mode == 2:
        return (-sine, -cosine)
    return (-cosine, sine)

ideal_spiral.normalized_source:
def _spiral_expression[derivatives: Bool](
    geometry: RoadGeometry,
    d: _JetExpression[derivatives],
    pieces: Int,
    translation: Vector3,
) -> Tuple[
    _JetExpression[derivatives],
    _JetExpression[derivatives],
    _JetExpression[derivatives],
]:
    comptime Expression = _JetExpression[derivatives]
    var k0 = Expression.constant(geometry.curvature_start)
    var rate = Expression.constant(
        (geometry.curvature_end - geometry.curvature_start) / geometry.length
    )
    var step = d / Expression.constant(Float64(pieces))
    var nodes = materialize[_GL_NODES]()
    var weights = materialize[_GL_WEIGHTS]()
    var x = Expression.constant(0.0)
    var y = Expression.constant(0.0)
    var piece = 0
    while piece < pieces:
        var start = step * Expression.constant(Float64(piece))
        var i = 0
        while i < 5:
            var t = (
                start
                + step * Expression.constant(0.5)
                * Expression.constant(1.0 + nodes[i])
            )
            var theta = Expression.constant(geometry.heading) + t * (
                k0 + Expression.constant(0.5) * rate * t
            )
            var trig = _sincos_expression(theta)
            x = (
                x
                + step
                * Expression.constant(0.5)
                * Expression.constant(weights[i])
                * trig[1]
            )
            y = (
                y
                + step
                * Expression.constant(0.5)
                * Expression.constant(weights[i])
                * trig[0]
            )
            i += 1
        piece += 1
    var heading = Expression.constant(geometry.heading) + d * (
        k0 + Expression.constant(0.5) * rate * d
    )
    return (
        (
            Expression.constant(geometry.x)
            - Expression.constant(Float64(translation.x))
        ) + x,
        (
            Expression.constant(geometry.y)
            + Expression.constant(Float64(translation.y))
        ) + y,
        heading,
    )
